import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type PizzaMergeProps = Record<string, any>;

const MUSHROOMS = [
  { x: -60, y: -90, r: -20 },
  { x: 90, y: -120, r: 40 },
  { x: 150, y: 70, r: 110 },
  { x: -140, y: 100, r: -60 },
  { x: 0, y: 160, r: 15 },
];

const PEPPERS = [
  { x: 60, y: -150, r: 80 },
  { x: -100, y: -30, r: -40 },
  { x: 100, y: 30, r: 45 },
  { x: -40, y: 100, r: -10 },
  { x: 160, y: -20, r: 120 },
];

const PEPPERONIS = [
  { x: 0, y: -120 },
  { x: 140, y: -40 },
  { x: -130, y: 20 },
  { x: 80, y: 130 },
  { x: -90, y: 140 },
  { x: 0, y: 40 },
];

const PizzaMerge: React.FC<PizzaMergeProps> = ({
  backgroundColor = "#1b1b1f",
  transparentBackground = false,
  durationInSeconds = 5,
  title = "The Perfect Slice",
  crustColor = "#E38D33",
  cheeseColor = "#F6C542",
  pepperoniColor = "#CD3B32",
  mushroomColor = "#FDF3DA",
  pepperColor = "#60A946",
  outlineColor = "#FFFFFF",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  // Responsive scale factor
  const s = Math.min(width, height) / 1080;

  // Geometry Base (Radius 300 in local unscaled coordinates)
  const R = 300;
  // Equilateral triangle inscribed in a circle of radius R (centroid at 0,0)
  const pt1 = `0,${-R}`;
  const pt2 = `${R * 0.866},${R * 0.5}`;
  const pt3 = `${-R * 0.866},${R * 0.5}`;
  const trianglePath = `M ${pt1} L ${pt2} L ${pt3} Z`;

  // Dynamic timing thresholds to ensure animations complete even on short durations
  const slideStart = Math.min(fps * 0.8, durationInFrames * 0.15);
  const bloomStart = Math.min(fps * 2.5, durationInFrames * 0.45);
  const textStart = Math.min(fps * 2.8, durationInFrames * 0.55);

  // Springs & Progress
  const sceneEntrance = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const slideSpring = spring({
    frame: frame - slideStart,
    fps,
    config: { damping: 15, mass: 1 },
  });

  const bloomSpring = spring({
    frame: frame - bloomStart,
    fps,
    config: { damping: 12, mass: 1 },
  });

  const textSpring = spring({
    frame: frame - textStart,
    fps,
    config: { damping: 14 },
  });

  // Calculate coordinates
  // Start far apart (x=400 in local coords), slide to center (x=0)
  const offsetAmount = interpolate(slideSpring, [0, 1], [400, 0]);
  const triangleX = -offsetAmount;
  const circleX = offsetAmount;

  // Mask scaling to bloom the pizza out of the triangle shape
  const maskScale = interpolate(bloomSpring, [0, 1], [1, 2.5]);

  // Overall scene fades
  const exitFade = interpolate(
    frame,
    [durationInFrames - 15, durationInFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const opacity =
    interpolate(frame, [0, 15], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }) * exitFade;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceGroteskFamily,
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          opacity,
          transform: `scale(${sceneEntrance})`,
          transition: "none",
        }}
      >
        <svg
          style={{ width: "100%", height: "100%", position: "absolute" }}
          viewBox={`0 0 ${width} ${height}`}
        >
          <defs>
            <clipPath id="pizza-mask">
              <path
                d={trianglePath}
                // The mask operates in the coordinate space of the pizza group (circleX).
                // To keep the mask matching the visual triangle outline at triangleX,
                // we shift it by (triangleX - circleX) and then scale from its centroid.
                transform={`translate(${
                  triangleX - circleX
                }, 0) scale(${maskScale})`}
              />
            </clipPath>
          </defs>

          {/* Central Centered Group with responsive scaling */}
          <g transform={`translate(${width / 2}, ${height / 2}) scale(${s})`}>
            
            {/* Left/Moving Triangle Outline Backdrop (only visible if we want the line to cross empty space) */}
            {/* The white outline itself is rendered last, on top of everything. */}
            
            <g transform={`translate(${circleX}, 0)`}>
              {/* Pizza Group - Restricted to the intersecting Triangle Mask */}
              <g clipPath="url(#pizza-mask)">
                {/* Crust Base */}
                <circle r={R} fill={crustColor} />
                
                {/* Cheese Layer */}
                <circle r={260} fill={cheeseColor} />
                
                {/* Pepperonis */}
                {PEPPERONIS.map((p, i) => (
                  <circle
                    key={`pep-${i}`}
                    cx={p.x}
                    cy={p.y}
                    r={35}
                    fill={pepperoniColor}
                  />
                ))}

                {/* Mushrooms */}
                {MUSHROOMS.map((m, i) => (
                  <g
                    key={`mush-${i}`}
                    transform={`translate(${m.x}, ${m.y}) rotate(${m.r})`}
                  >
                    <path
                      d="M -18,0 C -18,-20 18,-20 18,0 L 8,0 L 8,15 L -8,15 L -8,0 Z"
                      fill={mushroomColor}
                    />
                  </g>
                ))}

                {/* Green Peppers */}
                {PEPPERS.map((p, i) => (
                  <path
                    key={`pep-g-${i}`}
                    d="M -15,-15 Q 15,0 -15,15"
                    fill="none"
                    stroke={pepperColor}
                    strokeWidth={8}
                    strokeLinecap="round"
                    transform={`translate(${p.x}, ${p.y}) rotate(${p.r})`}
                  />
                ))}
              </g>

              {/* Always-visible Circle Outline around the Pizza bounds */}
              <circle
                r={R}
                fill="none"
                stroke={outlineColor}
                strokeWidth={8}
              />
            </g>

            {/* Always-visible Triangle Outline */}
            <path
              d={trianglePath}
              fill="none"
              stroke={outlineColor}
              strokeWidth={8}
              strokeLinejoin="round"
              transform={`translate(${triangleX}, 0)`}
            />
          </g>
        </svg>

        {/* Revealed Title */}
        <div
          style={{
            position: "absolute",
            bottom: height * 0.12,
            fontSize: 48 * s,
            color: outlineColor,
            fontWeight: 600,
            letterSpacing: "0.05em",
            opacity: textSpring,
            transform: `translateY(${(1 - textSpring) * 30}px)`,
            transition: "none",
          }}
        >
          {title}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PizzaMerge;